package com.tracewayapp.traceway.opamp

import com.tracewayapp.traceway.core.Ids
import com.tracewayapp.traceway.internal.HttpResponse
import com.tracewayapp.traceway.internal.ManualScheduler
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test
import java.io.File
import java.security.MessageDigest

/**
 * The codec against opamp-go v0.25.0, the protobufs the Traceway backend
 * uses, in both directions.
 *
 * [OpampGoldens] holds opamp-go's bytes for the messages below; it is
 * generated by the Go program in `scripts/opamp-golden`:
 *
 *     cd scripts/opamp-golden
 *     GOFLAGS=-mod=mod go run . golden > \
 *       ../../traceway/src/test/java/com/tracewayapp/traceway/opamp/OpampGoldens.kt
 *
 * Every AgentToServer here must encode to opamp-go's exact bytes, and every
 * ServerToAgent golden must decode to what the backend meant. To also feed
 * the Kotlin encoder's output to opamp-go's decoder:
 *
 *     TRACEWAY_OPAMP_GOLDEN_OUT=/tmp/opamp.txt ./gradlew :traceway:testDebugUnitTest \
 *       --tests 'com.tracewayapp.traceway.opamp.OpampInteropTest' --rerun
 *     cd scripts/opamp-golden && GOFLAGS=-mod=mod go run . check /tmp/opamp.txt
 */
class OpampInteropTest {

    private val newUid = fromHex("ffeeddccbbaa99887766554433221100")
    private val settingsDocument = """{"schemaVersion":1,"replay":{"mode":"stream"}}"""
    private val capabilities = AgentCapabilities.REPORTS_STATUS or
        AgentCapabilities.ACCEPTS_REMOTE_CONFIG or
        AgentCapabilities.REPORTS_REMOTE_CONFIG or
        AgentCapabilities.REPORTS_HEARTBEAT
    private val customCapabilities = listOf(
        "io.traceway.sdk.buffer/v1",
        "io.traceway.sdk.capture/v1",
        "io.traceway.sdk.sequence-triggers/v1",
    )

    private fun sha256(text: String): ByteArray =
        MessageDigest.getInstance("SHA-256").digest(text.toByteArray(Charsets.UTF_8))

    /** The same messages, by the same names, as agentToServer() in main.go. */
    private fun agentToServer(): List<Triple<String, AgentToServer, String>> = listOf(
        Triple(
            "shared",
            AgentToServer(
                instanceUid = testUid,
                sequenceNum = 3,
                agentDescription = AgentDescription(
                    identifying = mapOf("service.name" to "shop-web"),
                    nonIdentifying = mapOf(
                        "service.version" to "2.3.1",
                        "browser.mobile" to true,
                        "seats" to 12,
                        "ratio" to 0.25,
                    ),
                ),
                capabilities = capabilities,
                remoteConfigStatus = RemoteConfigStatus(fromHex("abcd"), RemoteConfigStatuses.APPLIED),
                customCapabilities = customCapabilities.take(2),
            ),
            OpampGoldens.A2S_SHARED,
        ),
        Triple(
            "firstPoll",
            AgentToServer(
                instanceUid = testUid,
                sequenceNum = 0,
                agentDescription = AgentDescription(
                    identifying = mapOf(
                        "service.name" to "shop-android",
                        "service.instance.id" to Ids.bytesToUuid(testUid),
                    ),
                    nonIdentifying = mapOf(
                        "service.version" to "4.1.0",
                        "os.name" to "Android",
                        "os.version" to "14",
                        "device.manufacturer" to "Google",
                        "device.model.name" to "Pixel 8",
                        "app.build" to 412,
                        "session.id" to "0195f2a1-1111-7222-8333-444455556666",
                    ),
                ),
                capabilities = capabilities,
                customCapabilities = customCapabilities,
            ),
            OpampGoldens.A2S_FIRST_POLL,
        ),
        Triple(
            "applied",
            AgentToServer(
                instanceUid = testUid,
                sequenceNum = 1,
                agentDescription = AgentDescription(mapOf("service.name" to "shop-android"), emptyMap()),
                capabilities = capabilities,
                remoteConfigStatus = RemoteConfigStatus(sha256(settingsDocument), RemoteConfigStatuses.APPLIED),
                customCapabilities = customCapabilities,
            ),
            OpampGoldens.A2S_APPLIED,
        ),
        Triple(
            "failed",
            AgentToServer(
                instanceUid = testUid,
                sequenceNum = 2,
                agentDescription = AgentDescription(mapOf("service.name" to "shop-android"), emptyMap()),
                capabilities = capabilities,
                remoteConfigStatus = RemoteConfigStatus(
                    fromHex("09"),
                    RemoteConfigStatuses.FAILED,
                    "bad: schemaVersion 9 ≠ 1 ✗",
                ),
            ),
            OpampGoldens.A2S_FAILED,
        ),
        Triple(
            "values",
            AgentToServer(
                instanceUid = testUid,
                sequenceNum = 300,
                agentDescription = AgentDescription(
                    identifying = mapOf("service.name" to "ünïcødé 🚀"),
                    nonIdentifying = linkedMapOf(
                        "flag" to false,
                        "n" to 0,
                        "big" to (1L shl 40),
                        "max" to Long.MAX_VALUE,
                        "neg" to -5,
                        "zero" to 0.0,
                        "half" to -0.5,
                        "float" to 1.5f,
                        "list" to listOf("a", "b"),
                        "none" to emptyList<String>(),
                        "empty" to "",
                        "" to "keyless",
                    ),
                ),
                capabilities = capabilities,
            ),
            OpampGoldens.A2S_VALUES,
        ),
        Triple(
            "emptyDescription",
            AgentToServer(
                instanceUid = testUid,
                sequenceNum = 5,
                agentDescription = AgentDescription(emptyMap(), emptyMap()),
                capabilities = capabilities,
            ),
            OpampGoldens.A2S_EMPTY_DESCRIPTION,
        ),
        Triple(
            "minimal",
            AgentToServer(instanceUid = testUid, sequenceNum = 0, capabilities = 0),
            OpampGoldens.A2S_MINIMAL,
        ),
    )

    /** What helperServerToAgent() in main.go expects these to decode to. */
    private fun helperServerToAgent(): List<Pair<String, ByteArray>> = listOf(
        "helperAll" to encodeServerToAgent(
            instanceUid = testUid,
            remoteConfig = RemoteConfig(
                configMap = mutableMapOf(
                    "traceway" to AgentConfigObject("""{"schemaVersion":1}""".toByteArray(), "application/json"),
                ),
                configHash = fromHex("0a0b"),
            ),
            heartbeatIntervalSeconds = 120,
            flags = SERVER_FLAG_REPORT_FULL_STATE,
            capabilities = 0x23,
            newInstanceUid = newUid,
        ),
        "helperError" to encodeServerToAgent(
            errorResponse = ServerErrorResponse(ServerErrorTypes.UNAVAILABLE, "busy", 60_000),
        ),
    )

    @Test
    fun `encodes every AgentToServer exactly as opamp-go`() {
        for ((name, message, golden) in agentToServer()) {
            assertEquals(name, golden, hex(encodeAgentToServer(message)))
        }
    }

    @Test
    fun `the test server's error response is opamp-go's`() {
        assertEquals(OpampGoldens.S2A_SHARED_ERROR, hex(helperServerToAgent()[1].second))
    }

    @Test
    fun `writes the encoder's output for the Go check`() {
        val path = System.getenv("TRACEWAY_OPAMP_GOLDEN_OUT") ?: return
        val lines = agentToServer().map { (name, message, _) -> "a2s $name ${hex(encodeAgentToServer(message))}" } +
            helperServerToAgent().map { (name, bytes) -> "s2a $name ${hex(bytes)}" }
        File(path).writeText(lines.joinToString("\n", postfix = "\n"))
    }

    @Test
    fun `decodes the backend's config answer`() {
        val msg = decodeServerToAgent(fromHex(OpampGoldens.S2A_REMOTE_CONFIG))
        assertEquals(hex(testUid), hex(msg.instanceUid!!))
        assertEquals(0x23L, msg.capabilities)
        assertEquals(0L, msg.flags)
        assertEquals(300L, msg.heartbeatIntervalSeconds)
        assertNull(msg.errorResponse)
        assertNull(msg.newInstanceUid)
        val config = msg.remoteConfig!!
        assertEquals(hex(sha256(settingsDocument)), hex(config.configHash))
        assertEquals(listOf("traceway"), config.configMap.keys.toList())
        assertEquals(settingsDocument, String(config.configMap["traceway"]!!.body, Charsets.UTF_8))
        assertEquals("application/json", config.configMap["traceway"]!!.contentType)
    }

    @Test
    fun `decodes a heartbeat-only answer`() {
        val msg = decodeServerToAgent(fromHex(OpampGoldens.S2A_HEARTBEAT))
        assertEquals(60L, msg.heartbeatIntervalSeconds)
        assertNull(msg.remoteConfig)
        assertEquals(0L, msg.flags)
    }

    @Test
    fun `decodes ReportFullState`() {
        val msg = decodeServerToAgent(fromHex(OpampGoldens.S2A_REPORT_FULL_STATE))
        assertEquals(SERVER_FLAG_REPORT_FULL_STATE, msg.flags)
        assertNull(msg.heartbeatIntervalSeconds)
        assertNull(msg.remoteConfig)
    }

    @Test
    fun `decodes the error responses`() {
        val unavailable = decodeServerToAgent(fromHex(OpampGoldens.S2A_UNAVAILABLE))
        assertEquals(0x23L, unavailable.capabilities)
        assertEquals(ServerErrorTypes.UNAVAILABLE, unavailable.errorResponse!!.type)
        assertEquals("remote config is temporarily unavailable", unavailable.errorResponse!!.message)
        assertEquals(60_000L, unavailable.errorResponse!!.retryAfterMs)

        val bad = decodeServerToAgent(fromHex(OpampGoldens.S2A_BAD_REQUEST))
        assertNull(bad.instanceUid)
        assertEquals(ServerErrorTypes.BAD_REQUEST, bad.errorResponse!!.type)
        assertEquals(
            "instance_uid must be 16 bytes and match the OpAMP-Instance-UID header",
            bad.errorResponse!!.message,
        )
        assertNull(bad.errorResponse!!.retryAfterMs)
    }

    @Test
    fun `decodes a new instance uid`() {
        val msg = decodeServerToAgent(fromHex(OpampGoldens.S2A_NEW_INSTANCE_UID))
        assertEquals(hex(newUid), hex(msg.newInstanceUid!!))
        assertEquals(hex(testUid), hex(msg.instanceUid!!))
        assertEquals(300L, msg.heartbeatIntervalSeconds)
    }

    @Test
    fun `decodes every entry of the config map`() {
        val config = decodeServerToAgent(fromHex(OpampGoldens.S2A_TWO_CONFIGS)).remoteConfig!!
        assertEquals(listOf("other", "traceway"), config.configMap.keys.toList())
        assertEquals(0, config.configMap["other"]!!.body.size)
        assertEquals("text/plain", config.configMap["other"]!!.contentType)
        assertEquals("""{"schemaVersion":1}""", String(config.configMap["traceway"]!!.body, Charsets.UTF_8))
        assertEquals("0a0b0c", hex(config.configHash))
    }

    @Test
    fun `reads what it needs from an answer full of fields it ignores`() {
        val msg = decodeServerToAgent(fromHex(OpampGoldens.S2A_IGNORED_FIELDS))
        assertEquals(45L, msg.heartbeatIntervalSeconds)
        assertEquals(3L, msg.flags)
        assertEquals(0x7fL, msg.capabilities)
        assertNull(msg.errorResponse)
        assertNull(msg.newInstanceUid)
        val config = msg.remoteConfig!!
        assertEquals("0d", hex(config.configHash))
        assertEquals("{}", String(config.configMap["traceway"]!!.body, Charsets.UTF_8))
        assertEquals("application/json", config.configMap["traceway"]!!.contentType)
    }

    @Test
    fun `a poll cycle against the backend's answers sends opamp-go's bytes`() {
        val scheduler = ManualScheduler()
        val bodies = ArrayList<ByteArray>()
        var applied: String? = null
        val client = OpampHttpClient(
            endpoint = "https://traceway.test/api/otel/v1/opamp",
            instanceUid = testUid,
            capabilities = capabilities,
            customCapabilities = customCapabilities,
            describe = { AgentDescription(mapOf("service.name" to "shop-android"), emptyMap()) },
            onRemoteConfig = { config ->
                applied = String(config.configMap["traceway"]!!.body, Charsets.UTF_8)
                ApplyResult.applied()
            },
            scheduler = scheduler,
            http = { _, _, body, _ ->
                bodies.add(body)
                val answer = if (bodies.size == 1) OpampGoldens.S2A_REMOTE_CONFIG else OpampGoldens.S2A_HEARTBEAT
                HttpResponse(200, emptyMap(), fromHex(answer))
            },
        )
        client.start()
        scheduler.runDue()
        client.stop()
        assertEquals(settingsDocument, applied)
        assertEquals(2, bodies.size)
        // The report of the applied config, byte for byte.
        assertEquals(OpampGoldens.A2S_APPLIED, hex(bodies[1]))
        assertEquals(60_000L, client.pollIntervalMs)
        // The first poll: no status yet.
        val first = AgentToServer(
            instanceUid = testUid,
            sequenceNum = 0,
            agentDescription = AgentDescription(mapOf("service.name" to "shop-android"), emptyMap()),
            capabilities = capabilities,
            customCapabilities = customCapabilities,
        )
        assertEquals(hex(encodeAgentToServer(first)), hex(bodies[0]))
    }
}
